def clasificar_catalogo_plantas(apps, schema_editor):
    Unidad = apps.get_model('webcitt', 'Unidad')
    EquiposServicios = apps.get_model('webcitt', 'EquiposServicios')
    FablabService = apps.get_model('webcitt', 'FablabService')

    Unidad.objects.filter(dependencia='plantas_piloto').update(
        modo_operacion='lotes', estado_catalogo='reserva_previa',
    )
    for tecnologia, codigos in TECNOLOGIAS_POR_EQUIPO.items():
        EquiposServicios.objects.filter(codigo__in=codigos).update(
            familia_tecnologica=tecnologia,
        )
    FablabService.objects.filter(
        unidad__dependencia='plantas_piloto', code__endswith='-SRV-MAQUILA',
    ).update(tipo_servicio='maquila_academica')
    FablabService.objects.filter(code='CAR-SRV-FORMULA').update(
        tipo_servicio='desarrollo_producto',
    )


